        } catch {
            ok = false;
        }

        // General property: After any admissible call (owner caller and amount>0), the reference contract never reduces
        // its own balance by transferring to the zero address because it rejects receiver==address(0). Therefore,
        // for ALL inputs the reference guarantees: if the call succeeded then receiver != address(0) and the contract
        // balance strictly decreased only when receiver != address(0). Equivalently, the contract balance after the
        // call equals the prior balance iff the call reverted or receiver==address(0) was rejected. We can test a
        // stronger universal observable: the reference never allows a successful call that results in a transfer to
        // address(0). Thus, assert that if the call succeeded (ok==true) then receiver != address(0) OR balance decreased.
        // But we must produce a single assertTrue reading c only. We observe address(c).balance to detect whether a
        // transfer out happened. For the reference contract, a call that succeeded implies receiver != address(0) and
        // therefore address(c).balance == 0 when amount == prior balance; to keep universal, we compare pre/post balances.

        // Capture post-balance and pre-balance: pre-balance was amount (we vm.deal'ed exactly amount), so preBalance = amount
        uint256 preBalance = amount;
